type Result<T>=std::result::Result<T,ValueError>;
type Field=(&'static str,Type,bool);
type Child=(&'static str,Domain,Role,bool,Option<&'static str>);
type Keys=&'static[(&'static str,&'static str)];
type Options=(&'static str,Option<&'static str>,Option<Keys>);
#[derive(Clone,Copy,PartialEq)]enum Type{Text,Number,Scalar}
#[derive(Clone,Copy,PartialEq)]enum Role{One,List,Map}
#[derive(Clone,Copy,PartialEq)]enum Domain{Document,Margin,Theme,Palette,Table,Column,Row,Cell,Scale,Domain,Range,Coordinate,Layer,Transform,Layout,Encoding,Guide,Tick,GuideTitle,Title,Annotation,AnnotationText,Preset}
const SCALE_KEYS:Keys=&[("nice","number|boolean"),("clamp","boolean"),("padding","number"),("paddingInner","number"),("paddingOuter","number"),("align","number"),("round","boolean"),("base","number"),("exponent","number"),("constant","number"),("ticks","number"),("tickValues","array:number|string"),("tickFormat","string"),("interpolator","string"),("scheme","string"),("reverse","boolean"),("interval","string"),("unknown","scalar|null")];
const GUIDE_KEYS:Keys=&[("scale","string"),("orient","string"),("ticks","number"),("tickFormat","string"),("tickSize","number"),("minor","boolean"),("grid","boolean"),("offset","number")];
const ANNOTATION_KEYS:Keys=&[("x2","number"),("y2","number"),("width","number"),("height","number"),("radius","number")];
const CHANNELS:&[&str]=&["x","y","x2","y2","angle","endAngle","radius","innerRadius","size","shape","fill","stroke","strokeWidth","opacity","text","dash","width","order","detail","rotation"];
impl Domain{
 fn table(self)->&'static str{match self{Self::Document=>"chart_document",Self::Margin=>"chart_margin",Self::Theme=>"chart_theme",Self::Palette=>"chart_palette",Self::Table=>"chart_table",Self::Column=>"chart_column",Self::Row=>"chart_row",Self::Cell=>"chart_cell",Self::Scale=>"chart_scale",Self::Domain=>"chart_domain",Self::Range=>"chart_range",Self::Coordinate=>"chart_coordinate",Self::Layer=>"chart_layer",Self::Transform=>"chart_transform",Self::Layout=>"chart_layout",Self::Encoding=>"chart_encoding",Self::Guide=>"chart_guide",Self::Tick=>"chart_tick",Self::GuideTitle=>"chart_guide_title",Self::Title=>"chart_title",Self::Annotation=>"chart_annotation",Self::AnnotationText=>"chart_annotation_text",Self::Preset=>"chart_preset"}}
 fn ordered(self)->bool{matches!(self,Self::Palette|Self::Table|Self::Column|Self::Row|Self::Scale|Self::Domain|Self::Range|Self::Layer|Self::Transform|Self::Guide|Self::Tick|Self::Annotation|Self::Preset)}
 fn map(self)->bool{matches!(self,Self::Cell|Self::Encoding)}
 fn primitive(self)->Option<&'static str>{match self{Self::Palette|Self::Column=>Some("text"),Self::Cell=>Some("scalar|null"),Self::Domain|Self::Range|Self::Tick=>Some("number|string"),_=>None}}
 fn fields(self)->&'static[Field]{use Type::*;match self{Self::Document=>&[("width",Number,true),("height",Number,true),("language",Text,false)],Self::Margin=>&[("top",Number,true),("right",Number,true),("bottom",Number,true),("left",Number,true)],Self::Theme=>&[("name",Text,false),("appearance",Text,false)],Self::Table=>&[("name",Text,true)],Self::Scale=>&[("name",Text,true),("kind",Text,true)],Self::Coordinate|Self::Transform|Self::Guide=>&[("kind",Text,true)],Self::Layer=>&[("mark",Text,true),("data",Text,false)],Self::Layout=>&[("algorithm",Text,true)],Self::Encoding=>&[("column",Text,false),("scale",Text,false),("value",Scalar,false)],Self::GuideTitle|Self::Title|Self::AnnotationText=>&[("en",Text,true),("de",Text,true)],Self::Annotation=>&[("kind",Text,true),("x",Number,true),("y",Number,true)],Self::Preset=>&[("kind",Text,true),("data",Text,false)],_=>&[]}}
 fn flags(self)->&'static[&'static str]{match self{Self::Document=>&["tables","scales","guides","annotations","presets"],Self::Theme=>&["palette"],Self::Layer=>&["transform","encodings","options"],Self::Guide=>&["options","tickValues"],Self::Scale|Self::Coordinate|Self::Transform|Self::Layout|Self::Annotation|Self::Preset=>&["options"],_=>&[]}}
 fn options(self)->Option<Options>{match self{Self::Scale=>Some(("chart_scale_option",Some("chart_scale_tick"),Some(SCALE_KEYS))),Self::Coordinate=>Some(("chart_coordinate_option",Some("chart_coordinate_item"),None)),Self::Transform=>Some(("chart_transform_option",Some("chart_transform_item"),None)),Self::Layout=>Some(("chart_layout_option",None,None)),Self::Layer=>Some(("chart_layer_option",None,None)),Self::Guide=>Some(("chart_guide_option",None,None)),Self::Annotation=>Some(("chart_annotation_option",None,None)),Self::Preset=>Some(("chart_preset_option",None,None)),_=>None}}
 fn properties(self)->Option<(&'static str,Keys)>{match self{Self::Guide=>Some(("chart_guide_property",GUIDE_KEYS)),Self::Annotation=>Some(("chart_annotation_property",ANNOTATION_KEYS)),_=>None}}
 fn children(self)->&'static[Child]{use Role::*;match self{Self::Document=>&[("margin",Self::Margin,One,false,None),("theme",Self::Theme,One,false,None),("tables",Self::Table,List,false,Some("tables")),("scales",Self::Scale,List,false,Some("scales")),("coordinate",Self::Coordinate,One,false,None),("layers",Self::Layer,List,true,None),("guides",Self::Guide,List,false,Some("guides")),("title",Self::Title,One,false,None),("annotations",Self::Annotation,List,false,Some("annotations")),("presets",Self::Preset,List,false,Some("presets"))],Self::Theme=>&[("palette",Self::Palette,List,false,Some("palette"))],Self::Table=>&[("columns",Self::Column,List,true,None),("rows",Self::Row,List,true,None)],Self::Row=>&[("",Self::Cell,Map,true,None)],Self::Scale=>&[("domain",Self::Domain,List,true,None),("range",Self::Range,List,true,None)],Self::Layer=>&[("transform",Self::Transform,List,false,Some("transform")),("layout",Self::Layout,One,false,None),("encodings",Self::Encoding,Map,false,Some("encodings"))],Self::Guide=>&[("tickValues",Self::Tick,List,false,Some("tickValues")),("title",Self::GuideTitle,One,false,None)],Self::Annotation=>&[("text",Self::AnnotationText,One,false,None)],_=>&[]}}
 fn kinds(self)->&'static[&'static str]{match self{Self::Scale=>&["linear","log","pow","sqrt","symlog","identity","ordinal","band","point","quantile","quantize","threshold","sequential","diverging","temporal"],Self::Coordinate=>&["cartesian","polar","ternary","barycentric","parallel","logpolar","geographic"],Self::Transform=>&["filter","sort","group","aggregate","rollup","summary","fold","pivot","join","window","normalize","cumulative","bin","stack","quantile","kde","regression"],Self::Layout=>&["stack","bin","hexbin","beeswarm","jitter","pie","arc","chord","sankey","alluvial","treemap","partition","pack","force","tree","cluster","dag","bundling","voronoi","delaunay","hull","contour","density","projection"],Self::Layer=>&["bar","rect","heatmap","point","circle","symbol","line","area","band","trail","arc","pie","text","rule","link","path","polygon","ribbon"],Self::Guide=>&["axis","legend","grid"],Self::Annotation=>&["text","label","line","rule","rect","circle","point"],_=>&[]}}
}
fn invalid(reason:&str)->ValueError{ValueError::new(K::InvalidValue,reason)}
fn object(value:&DslValue)->Result<&[(String,DslValue)]>{match value{DslValue::Object(fields)=>Ok(fields),_=>Err(invalid("Chart field requires an object"))}}
fn array(value:&DslValue)->Result<&[DslValue]>{match value{DslValue::Array(items)=>Ok(items),_=>Err(invalid("Chart field requires an ordered array"))}}
fn text(value:&DslValue)->Result<&str>{match value{DslValue::String(value)=>Ok(value),_=>Err(invalid("Chart field requires TEXT"))}}
fn numeric(value:&DslValue)->Result<Number>{match value{DslValue::Number(value)if value.as_f64().is_finite()=>Ok(*value),_=>Err(invalid("Chart field requires a finite number"))}}
fn member<'a>(fields:&'a[(String,DslValue)],name:&str)->Option<&'a DslValue>{fields.iter().find(|(key,_)|key==name).map(|(_,value)|value)}
fn unique(fields:&[(String,DslValue)],writer:&mut RowWriter<'_,'_>)->Result<()>{
 writer.checkpoint()?;let phase=writer.phase();let mut keys=writer.allocate_frontier(fields.len())?;for(key,_)in fields{writer.push_frontier(&mut keys,key.as_str())?;}writer.sort_frontier(&mut keys,|left,right,control|compare_text(left,right,phase,control))?;for pair in keys.windows(2){if writer.compare_text(pair[0],pair[1])?.is_eq(){return Err(invalid("duplicate authored chart object member"))}}Ok(())
}
fn normative(domain:Domain,fields:&[(String,DslValue)])->Result<()>{
 if domain==Domain::Guide{
  if let Some(value)=member(fields,"ticks"){let value=numeric(value)?.as_f64();if value<1.0||value.fract()!=0.0{return Err(invalid("guide ticks must be an integer of at least one"))}}
  if let Some(value)=member(fields,"orient"){if !["top","right","bottom","left"].contains(&text(value)?){return Err(invalid("unknown guide orientation"))}}
 }
 if domain==Domain::Scale{if let Some(value)=member(fields,"options"){
  let options=object(value)?;
  for name in["nice","constant","ticks"]{if let Some(value)=member(options,name){if !(name=="nice"&&matches!(value,DslValue::Bool(_)))&&numeric(value)?.as_f64()<=0.0{return Err(invalid("positive scale option required"))}}}
  for name in["padding","paddingOuter"]{if let Some(value)=member(options,name){if numeric(value)?.as_f64()<0.0{return Err(invalid("nonnegative scale padding required"))}}}
  for name in["paddingInner","align"]{if let Some(value)=member(options,name){if !(0.0..=1.0).contains(&numeric(value)?.as_f64()){return Err(invalid("scale fraction must be between zero and one"))}}}
  if let Some(value)=member(options,"base"){let value=numeric(value)?.as_f64();if value<=0.0||value==1.0{return Err(invalid("scale base must be positive and differ from one"))}}
  if let Some(value)=member(options,"interpolator"){if !["number","round","rgb","lab","hcl","oklab"].contains(&text(value)?){return Err(invalid("unknown scale interpolator"))}}
  if let Some(value)=member(options,"interval"){if !["auto","day","week","month","year"].contains(&text(value)?){return Err(invalid("unknown scale interval"))}}
  if let Some(value)=member(options,"scheme"){if text(value)?.is_empty(){return Err(invalid("scale scheme must be nonempty"))}}
  if ["band","point"].contains(&text(member(fields,"kind").ok_or_else(||invalid("missing scale kind"))?)?)&&member(options,"unknown").is_some(){return Err(invalid("band and point scales do not admit unknown"))}
 }}Ok(())
}

fn admit(domain:Domain,value:&DslValue,writer:&mut RowWriter<'_,'_>)->Result<()>{let fields=object(value)?;unique(fields,writer)?;if domain==Domain::Row{return Ok(())}for(key,_)in fields{writer.checkpoint()?;if !domain.fields().iter().any(|field|field.0==key)&&!domain.children().iter().any(|child|child.0==key)&&!domain.flags().contains(&key.as_str())&&!domain.properties().is_some_and(|(_,keys)|keys.iter().any(|entry|entry.0==key))&&!(key=="options"&&domain.options().is_some()){return Err(invalid("unknown authored chart entity field"))}}
 for(name,_,required)in domain.fields(){if *required&&member(fields,name).is_none(){return Err(invalid("missing required chart entity field"))}}
 let kinds=domain.kinds();if !kinds.is_empty(){let key=if domain==Domain::Layer{"mark"}else if domain==Domain::Layout{"algorithm"}else{"kind"};if !kinds.contains(&text(member(fields,key).ok_or_else(||invalid("missing chart kind"))?)?){return Err(invalid("unknown chart entity kind"))}}
 if domain==Domain::Document{if numeric(member(fields,"width").ok_or_else(||invalid("missing width"))?)?.as_f64()<=0.0||numeric(member(fields,"height").ok_or_else(||invalid("missing height"))?)?.as_f64()<=0.0{return Err(invalid("chart dimensions must be positive"))}if let Some(language)=member(fields,"language"){if !["en","de"].contains(&text(language)?){return Err(invalid("unknown authored chart language"))}}}if domain==Domain::Theme{if let Some(value)=member(fields,"appearance"){if !["light","dark"].contains(&text(value)?){return Err(invalid("unknown chart appearance"))}}}if matches!(domain,Domain::Table|Domain::Preset)&&text(member(fields,if domain==Domain::Table{"name"}else{"kind"}).ok_or_else(||invalid("missing name"))?)?.is_empty(){return Err(invalid("empty chart entity name"))}normative(domain,fields)?;Ok(())
}
#[derive(Clone,Copy)]struct NumericText{bytes:[u8;32],len:usize}
impl NumericText{fn new(value:Number)->Result<Self>{let mut result=Self{bytes:[0;32],len:0};match value{Number::UInt(value)=>write!(result,"{value}"),Number::Int(value)=>write!(result,"{value}"),Number::Float(value)=>write!(result,"{value:e}")}.map_err(|_|invalid("number companion exceeds fixed finite decimal width"))?;Ok(result)}fn text(&self)->&str{std::str::from_utf8(&self.bytes[..self.len]).expect("numeric formatter emits ASCII")}}
impl std::fmt::Write for NumericText{fn write_str(&mut self,value:&str)->std::fmt::Result{let end=self.len.checked_add(value.len()).filter(|end|*end<=self.bytes.len()).ok_or(std::fmt::Error)?;self.bytes[self.len..end].copy_from_slice(value.as_bytes());self.len=end;Ok(())}}
fn kind(number:Number)->&'static str{match number{Number::UInt(_)=>"uint",Number::Int(_)=>"int",Number::Float(_)=>"float"}}
fn allowed(value:&DslValue,types:&str)->Result<()>{let name=match value{DslValue::Null=>"null",DslValue::Bool(_)=>"boolean",DslValue::Number(_)=>{numeric(value)?;"number"},DslValue::String(_)=>"string",_=>return Err(invalid("chart scalar has an unsupported variant"))};if types=="scalar|null"||types=="scalar"&&name!="null"||types.split('|').any(|entry|entry==name){Ok(())}else{Err(invalid("chart scalar disagrees with its field type"))}}
fn scalar_cells<'a>(value:&'a DslValue,types:&str,exact:&'a NumericText)->Result<[Cell<'a>;6]>{allowed(value,types)?;Ok(match value{DslValue::Null=>[Cell::Text("null"),Cell::Null,Cell::Null,Cell::Null,Cell::Null,Cell::Null],DslValue::Bool(value)=>[Cell::Text("boolean"),Cell::Null,Cell::Null,Cell::Integer(i64::from(*value)),Cell::Null,Cell::Null],DslValue::String(value)=>[Cell::Text("string"),Cell::Text(value),Cell::Null,Cell::Null,Cell::Null,Cell::Null],DslValue::Number(value)=>[Cell::Text("number"),Cell::Null,Cell::Real(value.as_f64()),Cell::Null,Cell::Text(kind(*value)),Cell::Text(exact.text())],_=>unreachable!()})}
fn exact(value:&DslValue)->Result<NumericText>{NumericText::new(match value{DslValue::Number(value)=>*value,_=>Number::UInt(0)})}
fn option_allowed(keys:Option<Keys>,name:&str)->Result<&'static str>{match keys{Some(keys)=>keys.iter().find(|entry|entry.0==name).map(|entry|entry.1).ok_or_else(||invalid("unknown scale or entity property")),None=>Ok("scalar")}}
fn project_map(writer:&mut RowWriter<'_,'_>,fields:&[(String,DslValue)],parent:i64,options:Options)->Result<()>{unique(fields,writer)?;for(name,value)in fields{writer.checkpoint()?;let types=option_allowed(options.2,name)?;if let DslValue::Array(items)=value{let item_table=options.1.ok_or_else(||invalid("this chart option does not admit an array"))?;if options.2.is_some()&&!types.starts_with("array:"){return Err(invalid("this chart option requires a scalar"))}let id=writer.insert(options.0,&[Cell::Integer(parent),Cell::Text(name),Cell::Text("array"),Cell::Null,Cell::Null,Cell::Null,Cell::Null,Cell::Null])?;for(ordinal,item)in items.iter().enumerate(){let exact=exact(item)?;let scalar=scalar_cells(item,types.strip_prefix("array:").unwrap_or("scalar"),&exact)?;let mut cells=[Cell::Null;8];cells[0]=Cell::Integer(id);cells[1]=Cell::Integer(i64::try_from(ordinal).map_err(|_|invalid("option ordinal overflow"))?);cells[2..].copy_from_slice(&scalar);writer.insert(item_table,&cells)?;}}else{if types.starts_with("array:"){return Err(invalid("chart option requires an array"))}let exact=exact(value)?;let scalar=scalar_cells(value,types,&exact)?;let mut cells=[Cell::Null;8];cells[0]=Cell::Integer(parent);cells[1]=Cell::Text(name);cells[2..].copy_from_slice(&scalar);writer.insert(options.0,&cells)?;}}Ok(())}
fn project(writer:&mut RowWriter<'_,'_>,domain:Domain,value:&DslValue,parent:Option<i64>,ordinal:Option<usize>,key:Option<&str>)->Result<i64>{
 writer.checkpoint()?;let mut cells=[Cell::Null;32];let mut at=0;if let Some(parent)=parent{cells[at]=Cell::Integer(parent);at+=1;}if domain.ordered(){cells[at]=Cell::Integer(i64::try_from(ordinal.ok_or_else(||invalid("missing ordinal"))?).map_err(|_|invalid("ordinal overflow"))?);at+=1;}if domain.map(){cells[at]=Cell::Text(key.ok_or_else(||invalid("missing map key"))?);at+=1;}
 let mut numbers=[NumericText{bytes:[0;32],len:0};8];for(index,(name,ty,_))in domain.fields().iter().enumerate(){if *ty!=Type::Text{if let Some(value)=member(object(value)?,name){numbers[index]=exact(value)?;}}}if let Some(types)=domain.primitive(){if types=="text"{cells[at]=Cell::Text(text(value)?);at+=1;}else{numbers[0]=exact(value)?;cells[at..at+6].copy_from_slice(&scalar_cells(value,types,&numbers[0])?);at+=6;}return writer.insert(domain.table(),&cells[..at])}
 admit(domain,value,writer)?;let fields=object(value)?;for(index,(name,ty,required))in domain.fields().iter().enumerate(){if let Some(value)=member(fields,name){match ty{Type::Text=>{cells[at]=Cell::Text(text(value)?);at+=1;},Type::Number=>{let value=numeric(value)?;cells[at..at+3].copy_from_slice(&[Cell::Real(value.as_f64()),Cell::Text(kind(value)),Cell::Text(numbers[index].text())]);at+=3;},Type::Scalar=>{cells[at..at+6].copy_from_slice(&scalar_cells(value,"scalar",&numbers[index])?);at+=6;}}}else{if *required{return Err(invalid("missing chart scalar field"))}at+=match ty{Type::Text=>1,Type::Number=>3,Type::Scalar=>6};}}
 for name in domain.flags(){cells[at]=Cell::Integer(i64::from(member(fields,name).is_some()));at+=1;}let id=writer.insert(domain.table(),&cells[..at])?;
 if let Some(options)=domain.options(){if let Some(value)=member(fields,"options"){project_map(writer,object(value)?,id,options)?;}}if let Some((table,keys))=domain.properties(){for(name,types)in keys{if let Some(value)=member(fields,name){let exact=exact(value)?;let scalar=scalar_cells(value,types,&exact)?;let mut cells=[Cell::Null;8];cells[0]=Cell::Integer(id);cells[1]=Cell::Text(name);cells[2..].copy_from_slice(&scalar);writer.insert(table,&cells)?;}}}
 for(name,child,role,required,_)in domain.children(){let member=if name.is_empty(){Some(value)}else{member(fields,name)};let Some(member)=member else{if *required{return Err(invalid("missing required chart collection"))}continue};match role{Role::One=>{project(writer,*child,member,Some(id),None,None)?;},Role::List=>for(ordinal,item)in array(member)?.iter().enumerate(){project(writer,*child,item,Some(id),Some(ordinal),None)?;},Role::Map=>{let entries=object(member)?;unique(entries,writer)?;for(key,item)in entries{if *child==Domain::Encoding&&!CHANNELS.contains(&key.as_str()){return Err(invalid("unknown chart encoding channel"))}project(writer,*child,item,Some(id),None,Some(key))?;}}}}Ok(id)
}
/// 🫳️ Validates the same full domain cells without producing a database or native output.
pub(super) fn forecast(snapshot:&ChartSnapshot,control:&mut SqliteSnapshotControl<'_>,phase:Phase)->Result<()>{let mut writer=RowWriter::borrowed(control,phase)?;project(&mut writer,Domain::Document,&snapshot.chart,None,None,None)?;writer.finish_borrowed()}
/// 📤️ Owns every authored chart relationship through the existing row writer.
pub(super) fn to_database(snapshot:&ChartSnapshot,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase>{let mut writer=RowWriter::new(SQL,control)?;project(&mut writer,Domain::Document,&snapshot.chart,None,None,None)?;writer.finish()}

struct Entry<'a>{table:usize,parent:i64,ordinal:i64,row:&'a SqliteRow,used:bool}
struct Index<'a>{database:&'a SqliteDatabase,entries:Vec<Entry<'a>>}
fn ordered_table(name:&str)->bool{matches!(name,"chart_palette"|"chart_table"|"chart_column"|"chart_row"|"chart_scale"|"chart_domain"|"chart_range"|"chart_scale_tick"|"chart_coordinate_item"|"chart_layer"|"chart_transform"|"chart_transform_item"|"chart_guide"|"chart_tick"|"chart_annotation"|"chart_preset")}
impl<'a> Index<'a>{
 fn new(database:&'a SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<Self>{validate_sqlite_database_schema_controlled(database,SQL,Phase::ReconstructSnapshot,control)?;control.check_database(database,Phase::ReconstructSnapshot)?;let count=database.tables.iter().try_fold(0usize,|count,table|count.checked_add(table.rows.len()).ok_or_else(||invalid("chart row count overflow")))?;let mut entries=reserve(count,control)?;
  for(table_index,table)in database.tables.iter().enumerate(){for row in &table.rows{control.checkpoint(Phase::ReconstructSnapshot,entries.len(),count)?;if row.rowid<=0||row.integer(0)?!=row.rowid{return Err(invalid("chart requires positive SQL surrogate identities"))}entries.push(Entry{table:table_index,parent:if table.name=="chart_document"{0}else{row.integer(1)?},ordinal:if ordered_table(&table.name){row.integer(2)?}else{0},row,used:false});}}
  heap_sort(&mut entries,Phase::ReconstructSnapshot,control,|a,b,_|Ok((a.table,a.parent,a.ordinal,a.row.rowid).cmp(&(b.table,b.parent,b.ordinal,b.row.rowid))))?;Ok(Self{database,entries})
 }
 fn group(&self,table:&str,parent:i64,ordered:bool,control:&mut SqliteSnapshotControl<'_>)->Result<Range<usize>>{let table=self.database.tables.iter().position(|value|value.name==table).ok_or_else(||invalid("missing chart domain table"))?;let start=self.entries.partition_point(|entry|(entry.table,entry.parent)<(table,parent));let end=self.entries.partition_point(|entry|(entry.table,entry.parent)<=(table,parent));if ordered{for(ordinal,entry)in self.entries[start..end].iter().enumerate(){control.checkpoint(Phase::ReconstructSnapshot,ordinal,end-start)?;if entry.ordinal!=i64::try_from(ordinal).map_err(|_|invalid("chart ordinal overflow"))?{return Err(invalid("chart ordinals must be contiguous"))}}}Ok(start..end)}
 fn take(&mut self,at:usize)->Result<&'a SqliteRow>{let entry=&mut self.entries[at];if entry.used{return Err(invalid("chart row consumed twice"))}entry.used=true;Ok(entry.row)}
 fn finish(&self,control:&mut SqliteSnapshotControl<'_>)->Result<()>{for(at,entry)in self.entries.iter().enumerate(){control.checkpoint(Phase::ReconstructSnapshot,at,self.entries.len())?;if !entry.used{return Err(invalid("orphaned or unconsumed chart entity"))}}Ok(())}
}
type Owner=DecodedFieldOwner<DslValue>;
fn owner(value:DslValue)->Owner{DecodedFieldOwner::new(value,DslValue::retire_decoded)}
fn object_owner(capacity:usize,control:&mut SqliteSnapshotControl<'_>)->Result<Owner>{Ok(owner(DslValue::Object(reserve(capacity,control)?)))}
fn array_owner(capacity:usize,control:&mut SqliteSnapshotControl<'_>)->Result<Owner>{Ok(owner(DslValue::Array(reserve(capacity,control)?)))}
fn add_object(target:&mut Owner,name:&str,mut value:Owner,control:&mut SqliteSnapshotControl<'_>)->Result<()>{let DslValue::Object(fields)=target.as_mut()else{unreachable!()};for(key,_)in fields.iter(){if compare_text(key,name,Phase::ReconstructSnapshot,control)?.is_eq(){return Err(invalid("duplicate chart object member"))}}let key=Reconstruction::new(control)?.text(name)?;if fields.len()==fields.capacity(){return Err(invalid("chart object exact capacity exhausted"))}fields.push((key,value.take()));Ok(())}
fn add_array(target:&mut Owner,mut value:Owner,control:&mut SqliteSnapshotControl<'_>)->Result<()>{let DslValue::Array(items)=target.as_mut()else{unreachable!()};if items.len()==items.capacity(){return Err(invalid("chart array exact capacity exhausted"))}items.push(value.take());Ok(())}
fn null(row:&SqliteRow,at:usize,width:usize)->Result<bool>{if row.values.get(at)!=Some(&SqliteValue::Null){return Ok(false)}if row.values.get(at..at+width).is_none_or(|values|values.iter().any(|value|*value!=SqliteValue::Null)){return Err(invalid("absent chart field has an unexpected payload"))}Ok(true)}
fn decimal(text:&str,integer:bool,unsigned:bool)->bool{let bytes=text.as_bytes();if bytes.is_empty()||bytes.len()>32||integer&&text=="-0"{return false}let mut at=0;if bytes[at]==b'-'{if unsigned{return false}at+=1;}if at==bytes.len(){return false}match bytes[at]{b'0'=>at+=1,b'1'..=b'9'=>{at+=1;while at<bytes.len()&&bytes[at].is_ascii_digit(){at+=1;}},_=>return false}if !integer&&bytes.get(at)==Some(&b'.'){at+=1;let start=at;while at<bytes.len()&&bytes[at].is_ascii_digit(){at+=1;}if at==start{return false}}if !integer&&bytes.get(at).is_some_and(|byte|matches!(byte,b'e'|b'E')){at+=1;if bytes.get(at).is_some_and(|byte|matches!(byte,b'+'|b'-')){at+=1;}let start=at;while at<bytes.len()&&bytes[at].is_ascii_digit(){at+=1;}if at==start{return false}}at==bytes.len()}
fn number_from(row:&SqliteRow,value_at:usize,kind_at:usize,exact_at:usize)->Result<Number>{let query=row.real(value_at)?;if !query.is_finite(){return Err(invalid("chart SQL number must be finite"))}let exact=row.text(exact_at)?;if exact.len()>32{return Err(invalid("chart exact number exceeds finite companion width"))}let kind=row.text(kind_at)?;if !decimal(exact,kind!="float",kind=="uint"){return Err(invalid("invalid exact chart numeric spelling"))}let expected=match kind{"uint"=>Number::UInt(exact.parse().map_err(|_|invalid("invalid exact chart unsigned integer"))?),"int"=>Number::Int(exact.parse().map_err(|_|invalid("invalid exact chart signed integer"))?),"float"=>Number::Float(exact.parse().map_err(|_|invalid("invalid exact chart float"))?),_=>return Err(invalid("unknown chart number variant"))};if !expected.as_f64().is_finite(){return Err(invalid("exact chart number must be finite"))}Ok(if query==expected.as_f64(){expected}else{Number::Float(query)})}
fn scalar_from(row:&SqliteRow,at:usize,types:&str,control:&mut SqliteSnapshotControl<'_>)->Result<Owner>{Reconstruction::new(control)?.scalar()?;let value=match row.text(at)?{"null"=>{if !null(row,at+1,5)?{return Err(invalid("chart NULL scalar has a payload"))}DslValue::Null},"string"=>{if !null(row,at+2,4)?{return Err(invalid("chart TEXT scalar has an unexpected payload"))}DslValue::String(Reconstruction::new(control)?.text(row.text(at+1)?)?)},"boolean"=>{if row.values.get(at+1)!=Some(&SqliteValue::Null)||row.values.get(at+2)!=Some(&SqliteValue::Null)||!null(row,at+4,2)?{return Err(invalid("chart boolean has an unexpected payload"))}DslValue::Bool(match row.integer(at+3)?{0=>false,1=>true,_=>return Err(invalid("chart boolean must be zero or one"))})},"number"=>{if row.values.get(at+1)!=Some(&SqliteValue::Null)||row.values.get(at+3)!=Some(&SqliteValue::Null){return Err(invalid("chart numeric scalar has an unexpected payload"))}DslValue::Number(number_from(row,at+2,at+4,at+5)?)},_=>return Err(invalid("unknown chart scalar variant"))};let mut result=owner(value);allowed(result.as_mut(),types)?;Ok(result)}
fn reconstruct_map(index:&mut Index<'_>,parent:i64,options:Options,control:&mut SqliteSnapshotControl<'_>)->Result<Owner>{let rows=index.group(options.0,parent,false,control)?;let mut result=object_owner(rows.len(),control)?;for at in rows{let row=index.take(at)?;let name=row.text(2)?;let types=option_allowed(options.2,name)?;let value=if row.text(3)?=="array"{let item_table=options.1.ok_or_else(||invalid("unexpected chart option array"))?;if options.2.is_some()&&!types.starts_with("array:")||!null(row,4,5)?{return Err(invalid("chart option array payload or field type"))}let items=index.group(item_table,row.rowid,true,control)?;let mut value=array_owner(items.len(),control)?;for at in items{let row=index.take(at)?;let item=scalar_from(row,3,types.strip_prefix("array:").unwrap_or("scalar"),control)?;add_array(&mut value,item,control)?;}value}else{if types.starts_with("array:"){return Err(invalid("chart option must be an array"))}scalar_from(row,3,types,control)?};add_object(&mut result,name,value,control)?;}Ok(result)}
fn reconstruct(index:&mut Index<'_>,domain:Domain,position:usize,control:&mut SqliteSnapshotControl<'_>)->Result<Owner>{let row=index.take(position)?;control.checkpoint(Phase::ReconstructSnapshot,0,0)?;let mut at=1+usize::from(domain!=Domain::Document)+usize::from(domain.ordered())+usize::from(domain.map());if let Some(types)=domain.primitive(){return if types=="text"{Ok(owner(DslValue::String(Reconstruction::new(control)?.text(row.text(at)?)?)))}else{scalar_from(row,at,types,control)}}let mapped=if domain==Domain::Row{index.group("chart_cell",row.rowid,false,control)?.len()}else{0};let capacity=mapped+domain.fields().len()+domain.children().len()+usize::from(domain.options().is_some())+domain.properties().map_or(0,|(_,keys)|keys.len());let mut result=object_owner(capacity,control)?;
 for(name,ty,required)in domain.fields(){let width=match ty{Type::Text=>1,Type::Number=>3,Type::Scalar=>6};if null(row,at,width)?{if *required{return Err(invalid("missing required chart scalar"))}}else{let value=match ty{Type::Text=>owner(DslValue::String(Reconstruction::new(control)?.text(row.text(at)?)?)),Type::Number=>{Reconstruction::new(control)?.scalar()?;owner(DslValue::Number(number_from(row,at,at+1,at+2)?))},Type::Scalar=>scalar_from(row,at,"scalar",control)?};add_object(&mut result,name,value,control)?;}at+=width;}
 let mut flags=[false;8];for(index,_)in domain.flags().iter().enumerate(){flags[index]=match row.integer(at)?{0=>false,1=>true,_=>return Err(invalid("chart presence flag must be boolean"))};at+=1;}let present=|name:&str|domain.flags().iter().position(|field|*field==name).is_some_and(|at|flags[at]);
 if let Some(options)=domain.options(){let mut values=reconstruct_map(index,row.rowid,options,control)?;if present("options"){add_object(&mut result,"options",values,control)?;}else if !object(values.as_mut())?.is_empty(){return Err(invalid("chart options exist under an absent field"))}}
 if let Some((table,keys))=domain.properties(){let rows=index.group(table,row.rowid,false,control)?;for at in rows{let row=index.take(at)?;let name=row.text(2)?;let value=scalar_from(row,3,option_allowed(Some(keys),name)?,control)?;add_object(&mut result,name,value,control)?;}}
 for(name,child,role,required,flag)in domain.children(){let rows=index.group(child.table(),row.rowid,*role==Role::List,control)?;let is_present=*required||flag.map_or(!rows.is_empty(),present);if !is_present{if !rows.is_empty(){return Err(invalid("chart entities exist under an absent collection"))}continue}match role{Role::One=>{if rows.len()!=1{return Err(invalid("chart singular relationship must contain exactly one entity"))}let value=reconstruct(index,*child,rows.start,control)?;add_object(&mut result,name,value,control)?;},Role::List=>{let mut values=array_owner(rows.len(),control)?;for at in rows{let value=reconstruct(index,*child,at,control)?;add_array(&mut values,value,control)?;}add_object(&mut result,name,values,control)?;},Role::Map=>{let mut values=if name.is_empty(){None}else{Some(object_owner(rows.len(),control)?)};for at in rows{let key=index.entries[at].row.text(2)?;if *child==Domain::Encoding&&!CHANNELS.contains(&key){return Err(invalid("unknown chart encoding channel"))}let value=reconstruct(index,*child,at,control)?;add_object(values.as_mut().unwrap_or(&mut result),key,value,control)?;}if let Some(values)=values{add_object(&mut result,name,values,control)?;}}}}
 Ok(result)
}
/// 📥️ Consumes every real borrowed row and preserves all exact native scalar variants.
pub(super) fn from_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<ChartSnapshot>{let mut index=Index::new(database,control)?;let roots=index.group("chart_document",0,false,control)?;if roots.len()!=1{return Err(invalid("exactly one chart document is required"))}let mut chart=reconstruct(&mut index,Domain::Document,roots.start,control)?;index.finish(control)?;let mut snapshot=DecodedFieldOwner::new(ChartSnapshot{chart:chart.take()},ChartSnapshot::retire_decoded);forecast(snapshot.as_mut(),control,Phase::ReconstructSnapshot)?;Ok(snapshot.take())}
